import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Scraper Data","description":"","frontmatter":{"prev":{"text":"Excel Template","link":"/documentation/site/site-excel-template"},"next":{"text":"Site Settings","link":"/documentation/site/site-settings"}},"headers":[],"relativePath":"documentation/site/site-scraper-data.md","filePath":"documentation/site/site-scraper-data.md","lastUpdated":1788551488000}`),a={name:`documentation/site/site-scraper-data.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="scraper-data" tabindex="-1">Scraper Data <a class="header-anchor" href="#scraper-data" aria-label="Permalink to “Scraper Data”">​</a></h1><p>The <strong>Scraper Data</strong> workspace stores and manages datasets extracted from web pages using scraper field types during automated form workflows.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>When automating complex web portals, workflows often require extracting live data from web pages (such as order numbers, confirmation IDs, table entries, or verification codes) alongside filling inputs.</p><p>Whenever forms or segments execute with scraper field types enabled, the extracted records are automatically captured and organized within the <strong>Scraper Data</strong> tab of the active site:</p><ul><li><strong>Structured Storage</strong>: Catalogs extracted text, HTML elements, and table cells under structured field names.</li><li><strong>Excel Export</strong>: Download datasets directly as <code>.xlsx</code> spreadsheets for analysis, archiving, or feeding into subsequent automation steps.</li><li><strong>Session Control</strong>: View live records, refresh in-memory datasets, and purge old data to start fresh.</li></ul><hr><h2 id="when-scraper-data-appears" tabindex="-1">When Scraper Data Appears <a class="header-anchor" href="#when-scraper-data-appears" aria-label="Permalink to “When Scraper Data Appears”">​</a></h2><p>The Scraper Data interface and records become active when the following prerequisites are met:</p><ol><li><strong>Scraper Fields Configured</strong>: The active site has one or more fields assigned to a scraper field type (e.g., text scraper, attribute extractor, or table scraper).</li><li><strong>Form Automation Executed</strong>: The target web page has been processed with automation enabled (<kbd>Alt</kbd> + <kbd>Q</kbd> or page-load trigger).</li><li><strong>Data Captured</strong>: Elements matching your selectors were located in the DOM and values were retrieved.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If no scraper field types are configured for the site, or if the form has not been executed yet, the tab will display:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Scraper Data Not Available</span></span></code></pre></div><p>Learn more about configuring scraper field types in <a href="/documentation/form-fields/field-types.html">Supported Field Types</a>.</p></div><hr><h2 id="available-actions" tabindex="-1">Available Actions <a class="header-anchor" href="#available-actions" aria-label="Permalink to “Available Actions”">​</a></h2><p>The Scraper Data toolbar provides export and management actions:</p><table tabindex="0"><thead><tr><th>Action Button</th><th>Output / Behavior</th><th>Best For</th></tr></thead><tbody><tr><td><strong>Download Scraper Data</strong></td><td>Multi-sheet <code>.xlsx</code> workbook</td><td>Comprehensive data export containing dedicated sheets for distinct scraped forms and entity groups.</td></tr><tr><td><strong>Download Scraper Data Single Sheet</strong></td><td>Consolidated single-sheet <code>.xlsx</code></td><td>Quick reviews, flat data tables, or spreadsheets requiring straightforward row-by-row filtering.</td></tr><tr><td><strong>Refresh Data</strong></td><td>Re-queries stored memory</td><td>Updates the on-screen display if new records were scraped while the tab remained open.</td></tr><tr><td><strong>Delete Data</strong></td><td>Clears scraped records</td><td>Permanently removes current scraped records from the extension storage for this site.</td></tr></tbody></table><hr><h2 id="how-to-generate-scraper-data" tabindex="-1">How to Generate and Export Scraper Data <a class="header-anchor" href="#how-to-generate-scraper-data" aria-label="Permalink to “How to Generate and Export Scraper Data”">​</a></h2><p>Follow this complete step-by-step workflow:</p><h3 id="step-1-configure-scraper-fields" tabindex="-1">Step 1: Configure Scraper Fields <a class="header-anchor" href="#step-1-configure-scraper-fields" aria-label="Permalink to “Step 1: Configure Scraper Fields”">​</a></h3><ol><li>Open your <strong>Site</strong> and select the target <strong>Form</strong> or <strong>Segment</strong>.</li><li>Add a new field and select the appropriate scraper field type.</li><li>Configure the DOM selector (CSS Selector or XPath) matching the target text or table element on the web page.</li><li>Set any required <a href="/documentation/form-fields/field-settings.html#timing-settings">Timing Delays</a> if the target content loads asynchronously via JavaScript.</li></ol><h3 id="step-2-run-form-automation" tabindex="-1">Step 2: Run Form Automation <a class="header-anchor" href="#step-2-run-form-automation" aria-label="Permalink to “Step 2: Run Form Automation”">​</a></h3><ol><li>Navigate to the target web page.</li><li>Ensure the extension is enabled and trigger automation using <kbd>Alt</kbd> + <kbd>Q</kbd>.</li><li>The extension processes form steps, locates the scraper target elements, and extracts their values into memory.</li></ol><h3 id="step-3-inspect-and-export-scraped-data" tabindex="-1">Step 3: Inspect and Export Scraped Data <a class="header-anchor" href="#step-3-inspect-and-export-scraped-data" aria-label="Permalink to “Step 3: Inspect and Export Scraped Data”">​</a></h3><ol><li>Open the extension popup or options dashboard.</li><li>Navigate to your <strong>Site</strong> workspace and select the <strong>Scraper Data</strong> tab.</li><li>Review the extracted records displayed in the table.</li><li>Click <strong>Download Scraper Data</strong> or <strong>Download Scraper Data Single Sheet</strong> to export the data into a clean <code>.xlsx</code> file.</li></ol><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><h3 id="common-extraction-issues" tabindex="-1">Common Extraction Issues <a class="header-anchor" href="#common-extraction-issues" aria-label="Permalink to “Common Extraction Issues”">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>&quot;Scraper Data Not Available&quot; message</strong></td><td>No scraper fields configured, or automation hasn&#39;t run</td><td>Ensure at least one scraper field exists in the active form/segment and execute the workflow.</td></tr><tr><td><strong>Empty or null values captured</strong></td><td>Target element rendered after extraction attempt</td><td>Add a delay in <strong>Delay Time Before Running This Field</strong> (e.g., <code>1000ms</code> or <code>2000ms</code>) to allow dynamic content to load.</td></tr><tr><td><strong>Incorrect element scraped</strong></td><td>Non-unique CSS selector or dynamic DOM IDs</td><td>Inspect the element using <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd> and use a stable class or XPath expression.</td></tr><tr><td><strong>Download does not start</strong></td><td>Browser download permission prompt blocked</td><td>Check browser permissions for extension downloads or check browser download shelf.</td></tr></tbody></table><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Use Stable Selectors</strong>: Avoid auto-generated selectors with dynamic numerical IDs; use semantic class names, data attributes, or precise XPath queries.</li><li><strong>Account for Dynamic Rendering</strong>: Use appropriate before/after delays for AJAX or Single Page Application (SPA) elements.</li><li><strong>Clear Old Data Between Runs</strong>: Click <strong>Delete Data</strong> before initiating a new batch if you do not want previous session records mixed with fresh results.</li><li><strong>Validate Selectors with Inspect Element</strong>: Use <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd> on the target page to confirm your selector matches the exact node containing text.</li></ul><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-excel-template.html">Excel Template</a></li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/site/site.html">Site Management</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a></li><li><img src="/svg/database.svg" class="doc-icon"> <a href="/documentation/form-fields/field-types.html">Field Types Guide</a></li><li><img src="/svg/beaker.svg" class="doc-icon"> <a href="/documentation/logs.html">Execution Logs</a></li><li><img src="/svg/template.svg" class="doc-icon"> <a href="/documentation/segment.html">Segments Routine Automation</a></li></ul>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};